                            selectCard: [1, Infinity],
                            filter(event, player) {
                                return player.countCards('he') > 0;
                            },
                            check(card) {
                                switch (ui.selected.cards.length) {
                                    case 0:
                                        return 8 - get.value(card);
                                    case 1:
                                        return 6 - get.value(card);
                                    case 2:
                                        return 3 - get.value(card);
                                }
                                return 0;
                            },
                            content() {
                                'step 0';
                                var list = get.cards(cards.length);
                                event.list = list;
                                player.showCards(list);
                                ('step 1');
                                var suits = [];
                                event.suits = suits;
                                for (var i = 0; i < event.list.length; i++) {
                                    suits.add(event.list[i].suit);
                                    event.list[i].discard();
                                }
                                ('step 2');
                                if (event.suits.includes('diamond')) {
                                    var list;
                                    if (_status.characterlist) {
                                        list = [];
                                        for (var i = 0; i < _status.characterlist.length; i++) {
                                            var name = _status.characterlist[i];
                                            if (lib.character[name][1] == 'shu') list.push(name);
                                        }
                                    } else if (_status.connectMode) {
                                        list = get.charactersOL(function (i) {
                                            return lib.character[i][1] != 'shu';
                                        });
                                    } else {
                                        list = get.gainableCharacters(function (info) {
                                            return info[1] == 'shu';
                                        });
                                    }
                                    var players = game.players.concat(game.dead);
                                    for (var i = 0; i < players.length; i++) {
                                        list.remove(players[i].name);
                                        list.remove(players[i].name1);
                                        list.remove(players[i].name2);
                                    }
                                    list = list.randomGets(Math.max(4, game.countPlayer()));
                                    var skills = [];
                                    for (var i of list) {
                                        skills.addArray(
                                            (lib.character[i][3] || []).filter(function (skill) {
                                                var info = get.info(skill);
                                                return info && !info.zhuSkill && !info.limited && !info.juexingji && !info.hiddenSkill && !info.charlotte && !info.dutySkill;
                                            })
                                        );
                                    }
                                    if (!list.length || !skills.length) {
                                        event.finish();
                                        return;
                                    }
                                    if (player.isUnderControl()) {
                                        game.swapPlayerAuto(player);
                                    }
                                    var switchToAuto = function () {
                                        _status.imchoosing = false;
                                        event._result = {
                                            bool: true,
                                            skills: skills.randomGets(2),
                                        };
                                        if (event.dialog) event.dialog.close();
                                        if (event.control) event.control.close();
                                    };
                                    var chooseButton = function (list, skills) {
                                        var event = _status.event;
                                        if (!event._result) event._result = {};
                                        event._result.skills = [];
                                        var rSkill = event._result.skills;
                                        var dialog = ui.create.dialog('请选择获得1个技能', [list, 'character'], 'hidden');
                                        event.dialog = dialog;
                                        var table = document.createElement('div');
                                        table.classList.add('add-setting');
                                        table.style.margin = '0';
                                        table.style.width = '100%';
                                        table.style.position = 'relative';
                                        for (var i = 0; i < skills.length; i++) {
                                            var td = ui.create.div('.shadowed.reduce_radius.pointerdiv.tdnode');
                                            td.link = skills[i];
                                            table.appendChild(td);
                                            td.innerHTML = '<span>' + get.translation(skills[i]) + '</span>';
                                            td.addEventListener(lib.config.touchscreen ? 'touchend' : 'click', function () {
                                                if (_status.dragged) return;
                                                if (_status.justdragged) return;
                                                _status.tempNoButton = true;
                                                setTimeout(function () {
                                                    _status.tempNoButton = false;
                                                }, 500);
                                                var link = this.link;
                                                if (!this.classList.contains('bluebg')) {
                                                    if (rSkill.length >= 1) return;
                                                    rSkill.add(link);
                                                    this.classList.add('bluebg');
                                                } else {
                                                    this.classList.remove('bluebg');
                                                    rSkill.remove(link);
                                                }
                                            });
                                        }
                                        dialog.content.appendChild(table);
                                        dialog.add('　　');
                                        dialog.open();
                                        event.switchToAuto = function () {
                                            event.dialog.close();
                                            event.control.close();
                                            game.resume();
                                            _status.imchoosing = false;
                                        };
                                        event.control = ui.create.control('ok', function (link) {
                                            event.dialog.close();
                                            event.control.close();
                                            game.resume();
                                            _status.imchoosing = false;
                                        });
                                        for (var i = 0; i < event.dialog.buttons.length; i++) {
                                            event.dialog.buttons[i].classList.add('selectable');
                                        }
                                        game.pause();
                                        game.countChoose();
                                    };
                                    if (event.isMine()) {
                                        chooseButton(list, skills);
                                    } else if (event.isOnline()) {
                                        event.player.send(chooseButton, list, skills);
                                        event.player.wait();
                                        game.pause();
                                    } else {
                                        switchToAuto();
                                    }
                                }
                                ('step 3');
                                var map = event.result || result;
                                if (map && map.skills && map.skills[0]) {
                                    for (var i of map.skills) player.addSkillLog(i);
                                } //QQQ
                                ('step 4');
                                if (event.suits.includes('heart')) {
                                    player.addTempSkill('qiangwu', { player: 'phaseEnd' });
                                    if (player.isDamaged()) {
                                        player.recover();
                                        player.addSkill('qiangwu', { player: 'phaseEnd' });
                                    } else {
                                        player.changeHujia();
                                    }
                                }
                                ('step 5');
                                if (event.suits.includes('club')) {
                                    var enemies = player.getEnemies();
                                    for (var i = 0; i < enemies.length; i++) {
                                        enemies[i].randomDiscard();
                                        enemies[i].addExpose(0.1);
                                        player.line(enemies[i], 'green');
                                    }
                                }
                                ('step 6');
                                if (event.suits.includes('spade')) {
                                    player.chooseTarget('令一名角色受到一点无来源的火属性伤害').ai = function (target) {
                                        return get.damageEffect(target, target, player, 'fire');
                                    };
                                } else {
                                    event.finish();
                                }
                                ('step 7');
                                if (result.bool) {
                                    player.line(result.targets[0], 'fire');
                                    result.targets[0].damage('fire', 'nosource', 'nocard');
                                }
                            },
