                        shuanglongchuanbiaomingtianzhong_empty: {},
                        sanlongfendouhaibenjing: {
                            trigger: {
                                player: 'phaseDiscardEnd',
                            },
                            filter(event, player) {
                                if (!event.cards) return false;
                                return true;
                            },
                            forced: true,
                            content() {
                                'step 0';
                                var cards = trigger.cards;
                                var basic = 0;
                                var trick = 0;
                                var equip = 0;
                                for (var i = 0; i < cards.length; i++) {
                                    if (get.type(cards[i]) == 'basic') basic = 1;
                                    if (get.type(cards[i]) == 'trick' || get.type(cards[i]) == 'delay') trick = 1;
                                    if (get.type(cards[i]) == 'equip') equip = 1;
                                }
                                event.count = basic + trick + equip;
                                if (event.count == 0) {
                                    event.finish();
                                    return;
                                } else if (
                                    !game.hasPlayer(function (current) {
                                        return current.countCards('ej') > 0;
                                    })
                                ) {
                                    event.goto(2);
                                } else {
                                    player
                                        .chooseTarget('请选择一名角色,弃置其场上的一张牌', function (card, player, target) {
                                            return target.countCards('ej') > 0;
                                        })
                                        .set('ai', function (target) {
                                            var player = _status.event.player;
                                            var att = get.attitude(player, target);
                                            if (att > 0) {
                                                var js = target.getCards('j');
                                                if (js.length) {
                                                    var jj = js[0].viewAs
                                                        ? {
                                                            name: js[0].viewAs,
                                                        }
                                                        : js[0];
                                                    if (jj.name == 'guohe' || js.length > 1 || get.effect(target, jj, target, player) < 0) {
                                                        return 2 * att;
                                                    }
                                                }
                                                if (target.getEquip('baiyin') && target.isDamaged() && get.recoverEffect(target, player, player) > 0) {
                                                    if (target.hp == 1 && !target.hujia) return 1.6 * att;
                                                    if (target.hp == 2) return 0.01 * att;
                                                    return 0;
                                                }
                                            }
                                            var es = target.getCards('e');
                                            var noe = target.hasSkillTag('noe');
                                            var noe2 = es.length == 1 && es[0].name == 'baiyin' && target.isDamaged();
                                            if (noe || noe2) return 0;
                                            if (att <= 0 && !es.length) return 1.5 * att;
                                            return -1.5 * att;
                                        });
                                }
                                ('step 1');
                                if (result.bool) {
                                    event.target = result.targets[0];
                                    player.discardPlayerCard('ej', event.target);
                                    player.removeSkill('sanlongfendouhaibenjing');
                                }
                                ('step 2');
                                if (event.count < 2) {
                                    event.finish();
                                    return;
                                } else if (
                                    !game.hasPlayer(function (current) {
                                        return player.inRange(current) && current != player;
                                    })
                                ) {
                                    event.goto(4);
                                } else {
                                    player.chooseTarget('请选择一名攻击范围外的角色,对其造成1点伤害', function (card, player, target) {
                                        return player != target;
                                    }).ai = function (target) {
                                        return get.damageEffect(target, player, player);
                                    };
                                }
                                ('step 3');
                                if (result.bool) {
                                    event.target = result.targets[0];
                                    event.target.damage();
                                }
                                ('step 4');
                                if (event.count < 3) {
                                    event.finish();
                                    return;
                                } else {
                                    player.storage.sanlongfendouhaibenjing = true;
                                }
                            },
                        },
