                        zymhuairou: {
                            popup: false,
                            trigger: {
                                player: 'damageEnd',
                            },
                            forced: true,
                            filter(event, player) {
                                return game.hasPlayer(function (current) {
                                    return current != player && Math.abs(current.countCards('h') - player.countCards('h')) <= 3;
                                });
                            },
                            huairoueffect(player, target, damage) {
                                var playerCount = player.countCards('h');
                                var targetCount = target.countCards('h');
                                var playerEffect = 0;
                                var targetEffect = 0;
                                playerEffect -= playerCount;
                                playerEffect += targetCount;
                                targetEffect -= targetCount;
                                targetEffect += playerCount;
                                var m = 0;
                                if (damage) m = -1;
                                if (player.hp + m < player.maxHp && playerCount > targetCount) {
                                    var re = get.recoverEffect(player, player, player);
                                    if (re > 0) {
                                        playerEffect += 1.5;
                                    } else if (re < 0) {
                                        playerEffect -= 2;
                                    }
                                }
                                if (target.hp < target.maxHp && targetCount > playerCount) {
                                    var re = get.recoverEffect(target, player, target);
                                    if (re > 0) {
                                        targetEffect += 1.5;
                                    } else if (re < 0) {
                                        targetEffect -= 2;
                                    }
                                }
                                var eff = 0;
                                eff += playerEffect;
                                var att = get.attitude(player, target);
                                if (att > 0) {
                                    eff += targetEffect;
                                } else if (att < 0) {
                                    eff -= targetEffect;
                                }
                                return eff;
                            },
                            content() {
                                'step 0';
                                player
                                    .chooseTarget(1, '你可以选择一名角色,与其交换手牌', function (card, player, target) {
                                        return player != target;
                                    })
                                    .set('ai', function (target) {
                                        return lib.skill.zymhuairou.huairoueffect(player, target);
                                    });
                                ('step 1');
                                if (result && result.targets && result.targets.length) {
                                    event.tar = result.targets[0];
                                    player.swapHandcards(event.tar);
                                } else {
                                    event.finish();
                                }
                                ('step 2');
                                var pcount = player.hp;
                                var tcount = event.tar.hp;
                                if (pcount < tcount) {
                                    player.recover();
                                } else if (pcount > tcount) {
                                    event.tar.recover();
                                }
                            },
                            ai: {
                                maixie: true,
                                maixie_hp: true,
                                effect: {
                                    target(card, player, target) {
                                        if (get.tag(card, 'damage')) {
                                            if (player.hasSkillTag('jueqing', false, target, true)) return [1, -2];
                                            if (target.hp <= 1) return;
                                            if (!target.hasFriend()) return;
                                            var arr = [];
                                            var _player = target;
                                            game.filterPlayer(function (target) {
                                                if (_player != target && Math.abs(target.countCards('h') - _player.countCards('h')) <= 3) {
                                                    arr.push(lib.skill.zymhuairou.huairoueffect(_player, target, true));
                                                    return true;
                                                }
                                                return false;
                                            });
                                            if (arr.length == 0) return;
                                            var max = Math.max.apply(this, arr);
                                            if (max > 0) {
                                                return [1, max];
                                            }
                                        }
                                    },
                                },
                            },
                        },
