                        zymlurulin: {
                            audio: 'ext:破剑茶寮2/audio:2',
                            trigger: {
                                player: 'phaseEnd',
                            },
                            content() {
                                'step 0';
                                player
                                    .chooseControl('1', '2', '3', 'cancel2')
                                    .set('prompt', get.prompt2(event.name))
                                    .set('ai', function () {
                                        var player = get.player();
                                        if (player.countCards('hs', { name: ['shan', 'wuxie'] }) > 2 && player.hp < 2) return 'cancel2';
                                        if (player.countCards('hs') < 5 && player.countCards('hs') > 1 && player.hp > 2) return '3';
                                        if (!player.countCards('hs', { name: 'wuxie' })) return '2';
                                        if (player.countCards('hs') > 1 && player.hp > 1) return '1';
                                    });
                                ('step 1');
                                if (result.control == 'cancel2') return;
                                var num = Number(result.control);
                                player.addTempSkill('zymlurulin_use', 'phaseUseEnd');
                                player.draw(num);
                                player.storage.zymlurulin = num;
                                var use = player.phaseUse(),
                                    after = game.createEvent(event.name, false, use);
                                use._zymlurulin = true;
                                use._control = num;
                                use._useCard = 0;
                                after._proto = use;
                                after.player = player;
                                event.next.remove(use);
                                use.next.remove(after);
                                use.after.push(after);
                                trigger.after.push(use);
                                after.setContent(function () {
                                    var evt = event._proto;
                                    if (evt && (evt._useCard || 0) < evt._control && lib.skill.zymlurulin_lim) player.addTempSkill('zymlurulin_lim', { player: 'phaseBegin' });
                                    player.removeSkill('zymlurulin_use', true);
                                });
                            },
                            subSkill: {
                                use: {
                                    silent: true,
                                    mark: true,
                                    marktext: '露',
                                    markcount(_, player) {
                                        var evt = _status.event,
                                            num = 0;
                                        while (evt.parent) {
                                            if (evt._zymlurulin === true) {
                                                num = evt._useCard || 0;
                                                break;
                                            }
                                            evt = evt.parent;
                                        }
                                        return Math.max(0, player.storage.zymlurulin - num);
                                    },
                                    trigger: {
                                        player: 'useCard',
                                    },
                                    content() {
                                        var evt = trigger.parent;
                                        while (evt.parent) {
                                            if (evt._zymlurulin === true) {
                                                evt._useCard = (evt._useCard || 0) + 1;
                                                break;
                                            }
                                            evt = evt.parent;
                                        }
                                        player.markSkill(event.name);
                                    },
                                },
                                lim: {
                                    mark: true,
                                    intro: {
                                        content(_, player) {
                                            switch (player.storage.zymlurulin) {
                                                case 3:
                                                    return '无法使用任何牌';
                                                case 2:
                                                    return '无法使用【闪】与【无懈可击】';
                                                case 1:
                                                    return '无法使用【闪】';
                                            }
                                        },
                                    },
                                    onremove(player) {
                                        player.storage.zymlurulin = 0;
                                    },
                                    mod: {
                                        cardSavable(card, player) {
                                            if (player.storage.zymlurulin == 3) return false;
                                        },
                                        cardUsable(card, player) {
                                            if (player.storage.zymlurulin == 3) return false;
                                            else if (player.storage.zymlurulin == 2) return !['shan', 'wuxie'].includes(card.name);
                                            else if (player.storage.zymlurulin == 1) return card.name != 'shan';
                                        },
                                        cardEnabled(card, player) {
                                            if (player.storage.zymlurulin == 3) return false;
                                            else if (player.storage.zymlurulin == 2) return !['shan', 'wuxie'].includes(card.name);
                                            else if (player.storage.zymlurulin == 1) return card.name != 'shan';
                                        },
                                    },
                                },
                            },
                        },
